:root {
  --ink: #26333b;
  --paper: #fffdf7;
  --line: #d9d4c8;
  --coral: #e66f5c;
  --coral-dark: #bd4e42;
}

.ticket {
  width: 440px;
  box-sizing: border-box;
  padding: 16px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.ticket-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--line);
}

.ticket h1 {
  margin: 0;
  color: var(--ink);
  font-size: 20px;
  line-height: 1.2;
}

.badge {
  padding: 4px 8px;
  color: var(--coral-dark);
  background: var(--coral);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.details {
  padding: 10px 0 14px;
  color: var(--ink);
  font-size: 14px;
  line-height: 1.5;
}

.details p {
  margin: 0;
}

.ticket button {
  width: 100%;
  padding: 9px 12px;
  color: var(--paper);
  background: var(--coral-dark);
  border: 0;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 700;
}
